     1→/**
     2→ * PyFree Lexer (토크나이저)
     3→ * Python + FreeLang 코드를 토큰 스트림으로 변환
     4→ *
     5→ * 기능:
     6→ * - Python 인덴트 처리 (INDENT/DEDENT)
     7→ * - 문자열 파싱 (f-string 포함)
     8→ * - 숫자 파싱 (int, float, hex, binary)
     9→ * - 주석 제거 (# Python, // FreeLang)
    10→ * - 혼합 문법 지원
    11→ */
    12→
    13→import {
    14→  Token,
    15→  TokenType,
    16→  ALL_KEYWORDS,
    17→  createToken,
    18→  PYTHON_KEYWORDS,
    19→  FREELANG_KEYWORDS,
    20→} from './tokens';
    21→
    22→export class PyFreeLexer {
    23→  private source: string;
    24→  private pos: number = 0;
    25→  private line: number = 1;
    26→  private column: number = 1;
    27→  private tokens: Token[] = [];
    28→  private indentStack: number[] = [0];
    29→  private currentIndent: number = 0;
    30→  private atLineStart: boolean = true;
    31→
    32→  constructor(source: string) {
    33→    this.source = source;
    34→  }
    35→
    36→  /**
    37→   * 메인: 소스 코드를 토큰 스트림으로 변환
    38→   */
    39→  tokenize(): Token[] {
    40→    this.tokens = [];
    41→    this.pos = 0;
    42→    this.line = 1;
    43→    this.column = 1;
    44→    this.indentStack = [0];
    45→    this.atLineStart = true;
    46→
    47→    while (this.pos < this.source.length) {
    48→      // 줄의 시작에서 인덴트 처리
    49→      if (this.atLineStart && !this.isAtLineEnd()) {
    50→        this.handleIndentation();
    51→      }
    52→
    53→      if (this.pos >= this.source.length) break;
    54→
    55→      const ch = this.current();
    56→
    57→      // 공백 스킵 (인덴트 후)
    58→      if (ch === ' ' || ch === '\t') {
    59→        this.advance();
    60→        continue;
    61→      }
    62→
    63→      // 개행
    64→      if (ch === '\n' || ch === '\r') {
    65→        this.addToken(TokenType.NEWLINE, ch);
    66→        if (ch === '\r' && this.peek() === '\n') this.advance();
    67→        this.advance();
    68→        this.line++;
    69→        this.column = 1;
    70→        this.atLineStart = true;
    71→        continue;
    72→      }
    73→
    74→      // 주석 (Python)
    75→      if (ch === '#') {
    76→        this.skipComment();
    77→        continue;
    78→      }
    79→
    80→      // 주석 (FreeLang) - Phase 17: // 는 floor division 연산자이므로, 이 부분 제거
    81→      // if (ch === '/' && this.peek() === '/') {
    82→      //   this.skipComment();
    83→      //   continue;
    84→      // }
    85→
    86→      // 문자열
    87→      if (ch === '"' || ch === "'") {
    88→        this.tokenizeString();
    89→        this.atLineStart = false;
    90→        continue;
    91→      }
    92→
    93→      // f-string
    94→      if (ch === 'f' && (this.peek() === '"' || this.peek() === "'")) {
    95→        this.tokenizeString(true);
    96→        this.atLineStart = false;
    97→        continue;
    98→      }
    99→
   100→      // 숫자
   101→      if (this.isDigit(ch)) {
   102→        this.tokenizeNumber();
   103→        this.atLineStart = false;
   104→        continue;
   105→      }
   106→
   107→      // 식별자 또는 키워드
   108→      if (this.isIdentifierStart(ch)) {
   109→        this.tokenizeIdentifier();
   110→        this.atLineStart = false;
   111→        continue;
   112→      }
   113→
   114→      // 연산자 & 기호
   115→      if (!this.tokenizeOperator()) {
   116→        // 미인식 문자
   117→        this.addToken(TokenType.ERROR, ch);
   118→        this.advance();
   119→      }
   120→      this.atLineStart = false;
   121→    }
   122→
   123→    // 파일 끝 인덴트 정리
   124→    while (this.indentStack.length > 1) {
   125→      this.indentStack.pop();
   126→      this.tokens.push(
   127→        createToken(TokenType.DEDENT, '', this.line, this.column)
   128→      );
   129→    }
   130→
   131→    this.addToken(TokenType.EOF, '');
   132→    return this.tokens;
   133→  }
   134→
   135→  /**
   136→   * 인덴트/뎈덴트 처리 (Python)
   137→   */
   138→  private handleIndentation(): void {
   139→    let indent = 0;
   140→
   141→    while (this.pos < this.source.length) {
   142→      const ch = this.current();
   143→      if (ch === ' ') {
   144→        indent += 1;
   145→        this.advance();
   146→      } else if (ch === '\t') {
   147→        indent += 8; // 탭 = 8 스페이스
   148→        this.advance();
   149→      } else {
   150→        break;
   151→      }
   152→    }
   153→
   154→    // 공백 줄은 무시
   155→    if (
   156→      this.pos >= this.source.length ||
   157→      this.current() === '\n' ||
   158→      this.current() === '#'
   159→    ) {
   160→      return;
   161→    }
   162→
   163→    const prevIndent = this.indentStack[this.indentStack.length - 1];
   164→
   165→    if (indent > prevIndent) {
   166→      this.indentStack.push(indent);
   167→      this.addToken(TokenType.INDENT, '');
   168→    } else if (indent < prevIndent) {
   169→      while (
   170→        this.indentStack.length > 1 &&
   171→        this.indentStack[this.indentStack.length - 1] > indent
   172→      ) {
   173→        this.indentStack.pop();
   174→        this.addToken(TokenType.DEDENT, '');
   175→      }
   176→    }
   177→
   178→    this.currentIndent = indent;
   179→  }
   180→
   181→  /**
   182→   * 문자열 파싱
   183→   */
   184→  private tokenizeString(isFString: boolean = false): void {
   185→    const quote = this.current();
   186→    const startPos = this.pos;
   187→    const startLine = this.line;
   188→    const startColumn = this.column;
   189→
   190→    let value = '';
   191→    if (isFString) value = 'f';
   192→
   193→    this.advance(); // 따옴표 건너뛰기
   194→
   195→    // 3중 따옴표 확인
   196→    const isTriple =
   197→      this.current() === quote && this.peek() === quote;
   198→    if (isTriple) {
   199→      this.advance();
   200→      this.advance();
   201→    }
   202→
   203→    // 문자열 콘텐츠
   204→    while (this.pos < this.source.length) {
   205→      const ch = this.current();
   206→
   207→      if (ch === quote) {
   208→        if (isTriple) {
   209→          if (
   210→            this.peek() === quote &&
   211→            this.peekAhead(1) === quote
   212→          ) {
   213→            this.advance();
   214→            this.advance();
   215→            this.advance();
   216→            break;
   217→          }
   218→        } else {
   219→          this.advance();
   220→          break;
   221→        }
   222→      }
   223→
   224→      if (ch === '\\') {
   225→        value += ch;
   226→        this.advance();
   227→        if (this.pos < this.source.length) {
   228→          value += this.current();
   229→          this.advance();
   230→        }
   231→      } else {
   232→        if (ch === '\n') this.line++;
   233→        value += ch;
   234→        this.advance();
   235→      }
   236→    }
   237→
   238→    this.tokens.push({
   239→      type: isFString ? TokenType.F_STRING : TokenType.STRING,
   240→      value,
   241→      line: startLine,
   242→      column: startColumn,
   243→      raw: this.source.substring(startPos, this.pos),
   244→    });
   245→  }
   246→
   247→  /**
   248→   * 숫자 파싱 (int, float, hex, binary, octal)
   249→   */
   250→  private tokenizeNumber(): void {
   251→    const startPos = this.pos;
   252→    const startLine = this.line;
   253→    const startColumn = this.column;
   254→
   255→    let value = '';
   256→
   257→    // 16진수 (0x)
   258→    if (this.current() === '0' && this.peek() === 'x') {
   259→      this.advance();
   260→      this.advance();
   261→      while (this.isHexDigit(this.current())) {
   262→        value += this.current();
   263→        this.advance();
   264→      }
   265→      this.addToken(TokenType.NUMBER, '0x' + value);
   266→      return;
   267→    }
   268→
   269→    // 2진수 (0b)
   270→    if (this.current() === '0' && this.peek() === 'b') {
   271→      this.advance();
   272→      this.advance();
   273→      while (this.current() === '0' || this.current() === '1') {
   274→        value += this.current();
   275→        this.advance();
   276→      }
   277→      this.addToken(TokenType.NUMBER, '0b' + value);
   278→      return;
   279→    }
   280→
   281→    // 정수 부분
   282→    while (this.isDigit(this.current())) {
   283→      value += this.current();
   284→      this.advance();
   285→    }
   286→
   287→    // 소수 부분
   288→    if (this.current() === '.' && this.isDigit(this.peek())) {
   289→      value += '.';
   290→      this.advance();
   291→      while (this.isDigit(this.current())) {
   292→        value += this.current();
   293→        this.advance();
   294→      }
   295→    }
   296→
   297→    // 지수 표기법
   298→    if (
   299→      this.current() === 'e' ||
   300→      this.current() === 'E'
   301→    ) {
   302→      value += this.current();
   303→      this.advance();
   304→      if (
   305→        this.current() === '+' ||
   306→        this.current() === '-'
   307→      ) {
   308→        value += this.current();
   309→        this.advance();
   310→      }
   311→      while (this.isDigit(this.current())) {
   312→        value += this.current();
   313→        this.advance();
   314→      }
   315→    }
   316→
   317→    this.addToken(TokenType.NUMBER, value);
   318→  }
   319→
   320→  /**
   321→   * 식별자 또는 키워드 파싱
   322→   */
   323→  private tokenizeIdentifier(): void {
   324→    const startPos = this.pos;
   325→    let value = '';
   326→
   327→    while (
   328→      this.isIdentifierContinue(this.current())
   329→    ) {
   330→      value += this.current();
   331→      this.advance();
   332→    }
   333→
   334→    // 키워드 확인
   335→    if (ALL_KEYWORDS.has(value)) {
   336→      this.addToken(
   337→        ALL_KEYWORDS.get(value) as TokenType,
   338→        value
   339→      );
   340→    } else {
   341→      this.addToken(TokenType.IDENTIFIER, value);
   342→    }
   343→  }
   344→
   345→  /**
   346→   * 연산자 및 기호 파싱
   347→   */
   348→  private tokenizeOperator(): boolean {
   349→    const ch = this.current();
   350→    const nextCh = this.peek();
   351→    const nextNextCh = this.peekAhead(2);
   352→
   353→    // 3글자 연산자 (먼저 체크)
   354→    const threeCharOps: Record<string, TokenType> = {
   355→      '//=': TokenType.DOUBLE_SLASH_ASSIGN,
   356→      '**=': TokenType.POWER_ASSIGN,
   357→      '<<=': TokenType.LSHIFT_ASSIGN,
   358→      '>>=': TokenType.RSHIFT_ASSIGN,
   359→    };
   360→
   361→    const threeChar = ch + nextCh + nextNextCh;
   362→    if (threeCharOps[threeChar]) {
   363→      this.addToken(threeCharOps[threeChar], threeChar);
   364→      this.advance();
   365→      this.advance();
   366→      this.advance();
   367→      return true;
   368→    }
   369→
   370→    // 2글자 연산자
   371→    const twoCharOps: Record<string, TokenType> = {
   372→      '==': TokenType.EQUAL_EQUAL,
   373→      '!=': TokenType.NOT_EQUAL,
   374→      '<=': TokenType.LESS_EQUAL,
   375→      '>=': TokenType.GREATER_EQUAL,
   376→      '->': TokenType.ARROW,
   377→      '=>': TokenType.FAT_ARROW,
   378→      '//': TokenType.DOUBLE_SLASH,
   379→      '**': TokenType.POWER,
   380→      '+=': TokenType.PLUS_ASSIGN,
   381→      '-=': TokenType.MINUS_ASSIGN,
   382→      '*=': TokenType.STAR_ASSIGN,
   383→      '/=': TokenType.SLASH_ASSIGN,
   384→      '%=': TokenType.PERCENT_ASSIGN,
   385→      '&=': TokenType.AMPERSAND_ASSIGN,
   386→      '|=': TokenType.PIPE_ASSIGN,
   387→      '^=': TokenType.CARET_ASSIGN,
   388→      '<<': TokenType.LSHIFT,
   389→      '>>': TokenType.RSHIFT,
   390→      '&&': TokenType.AND,
   391→      '||': TokenType.OR,
   392→    };
   393→
   394→    const twoChar = ch + nextCh;
   395→    if (twoCharOps[twoChar]) {
   396→      this.addToken(twoCharOps[twoChar], twoChar);
   397→      this.advance();
   398→      this.advance();
   399→      return true;
   400→    }
   401→
   402→    // 1글자 연산자
   403→    const oneCharOps: Record<string, TokenType> = {
   404→      '+': TokenType.PLUS,
   405→      '-': TokenType.MINUS,
   406→      '*': TokenType.STAR,
   407→      '/': TokenType.SLASH,
   408→      '%': TokenType.PERCENT,
   409→      '=': TokenType.ASSIGN,
   410→      '<': TokenType.LESS_THAN,
   411→      '>': TokenType.GREATER_THAN,
   412→      '!': TokenType.NOT,
   413→      '&': TokenType.AMPERSAND,
   414→      '|': TokenType.PIPE,
   415→      '^': TokenType.CARET,
   416→      '~': TokenType.TILDE,
   417→      '?': TokenType.QUESTION,
   418→      '(': TokenType.LPAREN,
   419→      ')': TokenType.RPAREN,
   420→      '[': TokenType.LBRACKET,
   421→      ']': TokenType.RBRACKET,
   422→      '{': TokenType.LBRACE,
   423→      '}': TokenType.RBRACE,
   424→      ',': TokenType.COMMA,
   425→      '.': TokenType.DOT,
   426→      ':': TokenType.COLON,
   427→      ';': TokenType.SEMICOLON,
   428→      '@': TokenType.AT,
   429→      '_': TokenType.UNDERSCORE,
   430→    };
   431→
   432→    if (oneCharOps[ch]) {
   433→      this.addToken(oneCharOps[ch], ch);
   434→      this.advance();
   435→      return true;
   436→    }
   437→
   438→    return false;
   439→  }
   440→
   441→  /**
   442→   * 주석 스킵
   443→   */
   444→  private skipComment(): void {
   445→    while (
   446→      this.pos < this.source.length &&
   447→      this.current() !== '\n'
   448→    ) {
   449→      this.advance();
   450→    }
   451→  }
   452→
   453→  // ==================== 유틸리티 ====================
   454→
   455→  private current(): string {
   456→    if (this.pos >= this.source.length) return '\0';
   457→    return this.source[this.pos];
   458→  }
   459→
   460→  private peek(offset: number = 1): string {
   461→    const pos = this.pos + offset;
   462→    if (pos >= this.source.length) return '\0';
   463→    return this.source[pos];
   464→  }
   465→
   466→  private peekAhead(offset: number): string {
   467→    const pos = this.pos + offset;
   468→    if (pos >= this.source.length) return '\0';
   469→    return this.source[pos];
   470→  }
   471→
   472→  private advance(): void {
   473→    if (this.pos < this.source.length) {
   474→      this.pos++;
   475→      this.column++;
   476→    }
   477→  }
   478→
   479→  private isAtLineEnd(): boolean {
   480→    let i = this.pos;
   481→    while (i < this.source.length) {
   482→      const ch = this.source[i];
   483→      if (ch === '\n' || ch === '\r') return true;
   484→      if (ch !== ' ' && ch !== '\t' && ch !== '#') return false;
   485→      i++;
   486→    }
   487→    return true;
   488→  }
   489→
   490→  private isDigit(ch: string): boolean {
   491→    return ch >= '0' && ch <= '9';
   492→  }
   493→
   494→  private isHexDigit(ch: string): boolean {
   495→    return this.isDigit(ch) || (ch >= 'a' && ch <= 'f') || (ch >= 'A' && ch <= 'F');
   496→  }
   497→
   498→  private isIdentifierStart(ch: string): boolean {
   499→    return (
   500→      (ch >= 'a' && ch <= 'z') ||
   501→      (ch >= 'A' && ch <= 'Z') ||
   502→      ch === '_'
   503→    );
   504→  }
   505→
   506→  private isIdentifierContinue(ch: string): boolean {
   507→    return (
   508→      this.isIdentifierStart(ch) ||
   509→      this.isDigit(ch)
   510→    );
   511→  }
   512→
   513→  private addToken(type: TokenType, value: string): void {
   514→    this.tokens.push(
   515→      createToken(type, value, this.line, this.column)
   516→    );
   517→  }
   518→}
   519→
   520→/**
   521→ * 헬퍼: 코드를 토큰화
   522→ */
   523→export function tokenize(source: string): Token[] {
   524→  const lexer = new PyFreeLexer(source);
   525→  return lexer.tokenize();
   526→}
